    codeLabel: 'PYTHON — COSINE SIMILARITY WITH NUMPY',
    code: `import numpy as np

def cosine_sim(a, b):
    return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b)))

q = np.array([1.0, 2.0, 0.0])
doc_match = np.array([2.0, 4.0, 0.0])   # same direction, 2x length
doc_diff  = np.array([0.0, 0.0, 3.0])   # orthogonal
print("Match:", round(cosine_sim(q, doc_match), 2), "| Diff:", round(cosine_sim(q, doc_diff), 2))`,
